# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
import pytest
from django.core.files.uploadedfile import SimpleUploadedFile

pytestmark = pytest.mark.django_db

USERS = "/api/v1/users/"


def test_coordinator_creates_student(auth_client, coordinator):
    response = auth_client(coordinator).post(
        USERS,
        {
            "email": "new@example.com",
            "full_name": "New Student",
            "role": "STUDENT",
            "registration_number": "S100",
            "send_invite": False,
        },
        format="json",
    )
    assert response.status_code == 201, response.content
    assert response.json()["student_profile"]["registration_number"] == "S100"


def test_coordinator_lists_and_filters_users(auth_client, coordinator, student):
    response = auth_client(coordinator).get(USERS, {"role": "STUDENT"})
    assert response.status_code == 200
    emails = [row["email"] for row in response.json()["results"]]
    assert student.email in emails
    assert coordinator.email not in emails


def test_non_coordinators_cannot_manage_users(auth_client, student, workplace_supervisor):
    assert auth_client(student).get(USERS).status_code == 403
    assert auth_client(workplace_supervisor).post(USERS, {}, format="json").status_code == 403


def test_role_cannot_be_changed(auth_client, coordinator, student):
    response = auth_client(coordinator).patch(
        f"{USERS}{student.id}/", {"role": "COORDINATOR"}, format="json"
    )
    assert response.status_code == 422
    assert response.json()["code"] == "role_immutable"


def test_coordinator_can_deactivate_a_user(auth_client, coordinator, student):
    response = auth_client(coordinator).patch(
        f"{USERS}{student.id}/", {"is_active": False}, format="json"
    )
    assert response.status_code == 200
    assert response.json()["is_active"] is False


def test_me_can_be_read_and_name_updated(auth_client, student):
    client = auth_client(student)
    assert client.get(f"{USERS}me/").json()["email"] == student.email
    response = client.patch(
        f"{USERS}me/",
        {"full_name": "Renamed", "role": "COORDINATOR"},
        format="json",
    )
    assert response.status_code == 200
    body = response.json()
    assert body["full_name"] == "Renamed"
    assert body["role"] == "STUDENT"  # read-only


def test_supervisor_picker_lists_only_supervisors(
    auth_client, coordinator, student, academic_supervisor, workplace_supervisor
):
    response = auth_client(coordinator).get("/api/v1/supervisors/")
    ids = {row["id"] for row in response.json()["results"]}
    assert str(academic_supervisor.id) in ids
    assert str(workplace_supervisor.id) in ids
    assert str(student.id) not in ids


def test_csv_import_runs_as_a_job(auth_client, coordinator):
    csv_bytes = (
        b"email,full_name,role,registration_number\n"
        b"a@example.com,A,STUDENT,R10\n"
        b"b@example.com,B,STUDENT,R11\n"
    )
    client = auth_client(coordinator)
    upload = SimpleUploadedFile("users.csv", csv_bytes, content_type="text/csv")
    response = client.post(
        f"{USERS}import/", {"file": upload, "send_invites": "false"}, format="multipart"
    )
    assert response.status_code == 202, response.content
    task_id = response.json()["task_id"]

    status_response = client.get(f"{USERS}import/{task_id}/")
    assert status_response.status_code == 200
    body = status_response.json()
    assert body["status"] == "SUCCESS"
    assert body["created"] == 2


def test_csv_import_status_is_private_to_the_uploader(auth_client, coordinator, make_user):
    upload = SimpleUploadedFile("users.csv", b"email,full_name,role\n", content_type="text/csv")
    task_id = (
        auth_client(coordinator)
        .post(f"{USERS}import/", {"file": upload}, format="multipart")
        .json()["task_id"]
    )
    other = make_user(role="COORDINATOR")
    assert auth_client(other).get(f"{USERS}import/{task_id}/").status_code == 404


def test_csv_import_rejects_non_csv(auth_client, coordinator):
    upload = SimpleUploadedFile("users.txt", b"hello", content_type="text/plain")
    response = auth_client(coordinator).post(
        f"{USERS}import/",
        {"file": upload},
        format="multipart",
    )
    assert response.status_code == 422


def test_password_reset_email_points_to_the_frontend(api_client, make_user, mailoutbox):
    user = make_user(email="forgot@example.com")
    response = api_client.post("/api/v1/auth/password/reset/", {"email": user.email}, format="json")
    assert response.status_code == 200, response.content
    assert len(mailoutbox) == 1
    assert "/reset-password/" in mailoutbox[0].body
